"""Visual local operations desk; bounded metadata and reviewed local defense."""
import re


def _take(html: str, element_id: str) -> tuple[str, str]:
    """Extract one complete composed element without runtime DOM relocation."""
    match = re.search(r'<([a-z][a-z0-9-]*)\b[^>]*\bid="' + re.escape(element_id) + r'"[^>]*>', html)
    if not match:
        raise AssertionError(f'operations composition missing {element_id}')
    depth = 0
    for tag in re.finditer(r'</?' + match[1] + r'\b[^>]*>', html[match.start():]):
        depth += -1 if tag[0].startswith('</') else 1
        if depth == 0:
            end = match.start() + tag.end()
            return html[:match.start()] + html[end:], html[match.start():end]
    raise AssertionError(f'operations composition unclosed {element_id}')


